package com.example.car_rental_sys.dao;

import com.example.car_rental_sys.model.SystemLog;

import java.util.List;

/**
 * Data Access Object contract for audit {@link SystemLog} entries.
 */
public interface SystemLogDAO extends GenericDAO<SystemLog, Integer> {

    /**
     * Retrieves the most recent system audit logs.
     *
     * @param limit maximum logs to return
     * @return list of recent system logs
     */
    List<SystemLog> findRecentLogs(int limit) throws DAOException;

    /**
     * Retrieves all logs generated by a specific user.
     *
     * @param userId user ID
     * @return list of user logs
     */
    List<SystemLog> findByUserId(int userId) throws DAOException;

    /**
     * Retrieves all logs for a specific action type (e.g. "LOGIN", "RENTAL_CREATE").
     *
     * @param actionType action identifier
     * @return list of matching logs
     */
    List<SystemLog> findByActionType(String actionType) throws DAOException;
}
